    private static Brush[] BuildPalette(string[] hexes)
    {
        var result = new Brush[hexes.Length];
        for (var i = 0; i < hexes.Length; i++)
        {
            // WPF BrushConverter + Freeze() → ImmutableSolidColorBrush (born frozen).
            result[i] = new ImmutableSolidColorBrush(Color.Parse(hexes[i]));
        }
        return result;
    }

