    /// <summary>Creates the view-model and begins watching for connected devices.</summary>
    public ChannelsPaneViewModel()
    {
        ToggleChannelCommand = new RelayCommand<ChannelTileViewModel>(ToggleChannel, _ => !IsLoggingActive);
        SelectAllCommand = new RelayCommand<string>(SelectAll, _ => !IsLoggingActive);
        ClearAllCommand = new RelayCommand(ClearAll, () => !IsLoggingActive);
        OpenSettingsCommand = new RelayCommand<ChannelTileViewModel>(OpenSettings);
        CloseSettingsCommand = new RelayCommand(CloseSettings);
        SetColorCommand = new RelayCommand<Brush>(SetColor);

        _valueRefreshTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(100) };
        _valueRefreshTimer.Tick += OnValueRefreshTick;
        _valueRefreshTimer.Start();

        ConnectionManager.Instance.PropertyChanged += OnConnectionManagerPropertyChanged;
        LoggingManager.Instance.PropertyChanged += OnLoggingManagerPropertyChanged;
        IsLoggingActive = LoggingManager.Instance.Active;
        Rebuild();
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.OnIsLoggingActiveChanged
    partial void OnIsLoggingActiveChanged(bool value)
    {
        ToggleChannelCommand.NotifyCanExecuteChanged();
        SelectAllCommand.NotifyCanExecuteChanged();
        ClearAllCommand.NotifyCanExecuteChanged();
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.OnLoggingManagerPropertyChanged
    private void OnLoggingManagerPropertyChanged(object? sender, PropertyChangedEventArgs e)
    {
        if (e.PropertyName == nameof(LoggingManager.Active))
        {
            // Marshal to the UI thread — Active can be toggled from background
            // threads (e.g., disk-space monitor stopping a session).
            if (Dispatcher.UIThread.CheckAccess())
            {
                IsLoggingActive = LoggingManager.Instance.Active;
            }
            else
            {
                Dispatcher.UIThread.Post(() => IsLoggingActive = LoggingManager.Instance.Active);
            }
        }
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.OnValueRefreshTick
    private void OnValueRefreshTick(object? sender, EventArgs e) =>
        ValueRefresh?.Invoke(this, EventArgs.Empty);

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.OnConnectionManagerPropertyChanged
    private void OnConnectionManagerPropertyChanged(object? sender, PropertyChangedEventArgs e)
    {
        if (e.PropertyName == nameof(ConnectionManager.ConnectedDevices))
        {
            // Marshal to the UI thread — ConnectedDevices can change from a background
            // thread (the mobile USB connector registers off-thread), and Rebuild
            // mutates Avalonia-bound collections which must be touched on the UI
            // thread. Matches OnLoggingManagerPropertyChanged and the Devices/DeviceLogs
            // handlers; on desktop (already UI-thread) CheckAccess short-circuits so
            // there's no behavior change (adversarial audit hardening).
            if (Dispatcher.UIThread.CheckAccess())
            {
                Rebuild();
            }
            else
            {
                Dispatcher.UIThread.Post(Rebuild);
            }
        }
    }

    /// <summary>
    /// Called by a tile when its channel's direction/output flips, so the
    /// tile can be re-shelved into the right section and its stripe/label
    /// updated. Deferred to the dispatcher to avoid mutating collections
    /// during the channel's own PropertyChanged notification.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.RequestSectionReshuffle
    internal void RequestSectionReshuffle()
    {
        Dispatcher.UIThread.Post(Rebuild, DispatcherPriority.Background);
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.Rebuild
    private void Rebuild()
    {
        if (_disposed) return;

        DisposeTiles(AnalogInputs);
        DisposeTiles(DigitalInputs);
        DisposeTiles(DigitalOutputs);
        ConnectedDeviceNames.Clear();
        _channelOwners.Clear();

        var devices = ConnectionManager.Instance.ConnectedDevices.ToList();
        HasConnectedDevice = devices.Count > 0;
        HasMultipleDevices = devices.Count > 1;
        DeviceName = devices.FirstOrDefault()?.Name ?? "";

        foreach (var device in devices)
        {
            ConnectedDeviceNames.Add(device.Name);
        }

        foreach (var device in devices)
        {
            foreach (var channel in device.DataChannels.NaturalOrderBy(c => c.Name))
            {
                _channelOwners[channel] = device;
                var tile = new ChannelTileViewModel(channel, this, device.Name, HasMultipleDevices);
                if (channel.IsAnalog && channel.Direction == ChannelDirection.Input)
                {
                    AnalogInputs.Add(tile);
                }
                else if (channel.IsDigital &&
                         (channel.Direction == ChannelDirection.Output || channel.IsPwmEnabled))
                {
                    // A PWM-active channel drives its pin regardless of the stored
                    // direction, so it shelves with the outputs (issue #664).
                    DigitalOutputs.Add(tile);
                }
                else if (channel.IsDigital)
                {
                    DigitalInputs.Add(tile);
                }
                else
                {
                    tile.Dispose();
                }
            }
        }
        RecomputeCounts();
        SyncSettingsDrawer();
    }

    /// <summary>
    /// Preserves the settings drawer across a rebuild while the channel it shows is still owned by a
    /// connected device, and closes it otherwise so it cannot sit over an empty pane pointing at gone
    /// hardware (issue #765). Ownership is resolved by object identity (not DeviceSerialNo — a blank
    /// serial is a real state here, so a string match can resolve to the wrong device or none): a
    /// metadata re-sync keeps the existing channel instance, and disconnecting empties DataChannels
    /// outright, so a channel absent from _channelOwners after a rebuild is one no connected device owns.
    /// </summary>
    private void SyncSettingsDrawer()
    {
        if (!IsSettingsOpen) return;

        var owner = SelectedChannel == null ? null : FindOwningDevice(SelectedChannel);
        if (owner == null)
        {
            CloseSettings();
            return;
        }

        // The drawer edits device-scoped state too (the device-wide PWM frequency), so point it at
        // the device that provably owns the channel.
        SelectedDevice = owner;
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.DisposeTiles
    private static void DisposeTiles(ObservableCollection<ChannelTileViewModel> tiles)
    {
        foreach (var tile in tiles) tile.Dispose();
        tiles.Clear();
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.RecomputeCounts
    private void RecomputeCounts()
    {
        ActiveAnalogCount = AnalogInputs.Count(t => t.IsActive);
        TotalAnalogCount = AnalogInputs.Count;
        ActiveDigitalInCount = DigitalInputs.Count(t => t.IsActive);
        TotalDigitalInCount = DigitalInputs.Count;
        ActiveDigitalOutCount = DigitalOutputs.Count(t => t.IsActive);
        TotalDigitalOutCount = DigitalOutputs.Count;
        TotalActive = ActiveAnalogCount + ActiveDigitalInCount + ActiveDigitalOutCount;
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.ToggleChannel
    private void ToggleChannel(ChannelTileViewModel? tile)
    {
        if (tile == null) return;
        var channel = tile.Channel;
        var device = FindOwningDevice(channel);
        if (device == null) return;

        if (channel.IsActive)
        {
            LoggingManager.Instance.Unsubscribe(channel);
            device.RemoveChannel(channel);
        }
        else
        {
            device.AddChannel(channel);
            LoggingManager.Instance.Subscribe(channel);
        }
        RecomputeCounts();
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.SelectAll
    private void SelectAll(string? section)
    {
        IEnumerable<ChannelTileViewModel> tiles = section switch
        {
            "AI" => AnalogInputs,
            "DI" => DigitalInputs,
            "DO" => DigitalOutputs,
            _ => [],
        };
        foreach (var tile in tiles.Where(t => !t.IsActive).ToList())
        {
            ToggleChannel(tile);
        }
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.ClearAll
    private void ClearAll()
    {
        var active = AnalogInputs
            .Concat(DigitalInputs)
            .Concat(DigitalOutputs)
            .Where(t => t.IsActive)
            .ToList();
        foreach (var tile in active) ToggleChannel(tile);
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.OpenSettings
    private void OpenSettings(ChannelTileViewModel? tile)
    {
        if (tile == null) return;
        SelectedChannel = tile.Channel;
        SelectedDevice = FindOwningDevice(tile.Channel);
        IsSettingsOpen = true;
    }

    /// <summary>
    /// Resolves the connected device that owns <paramref name="channel"/>, from the map
    /// <see cref="Rebuild"/> captured. Returns null once the owning device has left
    /// <see cref="ConnectionManager.ConnectedDevices"/>. Keyed by identity rather than
    /// <see cref="IChannel.DeviceSerialNo"/> (see <see cref="SyncSettingsDrawer"/> for why).
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.FindOwningDevice
    private Daqifi.Desktop.Device.IStreamingDevice? FindOwningDevice(IChannel channel)
    {
        var owner = _channelOwners.GetValueOrDefault(channel);
        if (owner == null)
        {
            return null;
        }

        // The map is only refreshed on Rebuild, so between a disconnect and the next Rebuild it can
        // still hold a device that has left ConnectedDevices. Confirm the owner is still connected so
        // a caller racing a disconnect (ToggleChannel/OpenSettings on a not-yet-removed tile) never
        // acts on gone hardware — this restores the null the old live serial scan returned. A snapshot
        // avoids racing a concurrent connect/disconnect mutation of the list.
        return ConnectionManager.Instance.ConnectedDevices.ToList().Contains(owner) ? owner : null;
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.CloseSettings
    private void CloseSettings()
    {
        IsSettingsOpen = false;
        SelectedChannel = null;
        SelectedDevice = null;
    }

    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.SetColor
    private void SetColor(Brush? brush)
    {
        if (SelectedChannel == null || brush == null) return;
        SelectedChannel.ChannelColorBrush = brush;
    }

    /// <summary>
    /// Stops the refresh timer, detaches the singleton subscription, and
    /// disposes every tile. Safe to call more than once.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ChannelsPaneViewModel.Dispose
    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;

        _valueRefreshTimer.Stop();
        _valueRefreshTimer.Tick -= OnValueRefreshTick;
        ConnectionManager.Instance.PropertyChanged -= OnConnectionManagerPropertyChanged;
        LoggingManager.Instance.PropertyChanged -= OnLoggingManagerPropertyChanged;

        DisposeTiles(AnalogInputs);
        DisposeTiles(DigitalInputs);
        DisposeTiles(DigitalOutputs);

        GC.SuppressFinalize(this);
    }
